# =============================================================================
# Pulse Docker Agent
# =============================================================================
# Deploys Pulse agent container for Docker monitoring
# Agent reports metrics to central Pulse server

resource "ansible_navigator_run" "configure_pulse_agent" {
  count = try(var.pulse_agent.enabled, false) ? 1 : 0

  triggers = {
    container_id = var.container_id
    container_ip = var.container_ip
    pulse_url    = var.pulse_agent.pulse_url
    pulse_token  = sha256(var.pulse_agent.pulse_token)
  }

  execution_environment = {
    enabled = false
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.proxmox_ssh_private_key_path)
    }]
