content.content:
     1→#!/usr/bin/env bash
     2→# =============================================================================
     3→# Container Registry for Backup Scripts
     4→# =============================================================================
     5→# Central source of truth for container IDs and backup configuration.
     6→# Source this file from other backup scripts.
     7→#
     8→# Usage in scripts:
     9→#   source "$(dirname "$0")/containers.sh"
    10→#   VMID=$(get_container_id "openwebui")
    11→# =============================================================================
    12→
    13→# -----------------------------------------------------------------------------
    14→# Backup Tiers
    15→# -----------------------------------------------------------------------------
    16→# Daily: User data that changes frequently (kept 7 days)
    17→# Weekly: Infrastructure that rarely changes (kept 4 weeks)
    18→
    19→DAILY_CONTAINERS="304 501 502"      # immich, openwebui, n8n
    20→WEEKLY_CONTAINERS="100 101 200 201 202 401 402 500"  # infrastructure
    21→
    22→# All containers to backup (excludes stateless/temporary)
    23→ALL_BACKUP_CONTAINERS="$WEEKLY_CONTAINERS $DAILY_CONTAINERS"
    24→
    25→# Excluded from backups (documented here for reference)
    26→# 303 = immich-importer (stateless, runs cron jobs only)
    27→# 600 = desktop-tmp (temporary GUI container)
    28→
    29→# -----------------------------------------------------------------------------
    30→# Container ID Lookup
    31→# -----------------------------------------------------------------------------
    32→# Get container ID by app name
    33→# Usage: VMID=$(get_container_id "openwebui")
    34→get_container_id() {
    35→    local app="$1"
    36→    case "$app" in
    37→        network-services)  echo "101" ;;
    38→        traefik)           echo "200" ;;
    39→        dashboards)        echo "201" ;;
    40→        authelia)          echo "202" ;;
    41→        immich)            echo "304" ;;
    42→        jellyfin)          echo "401" ;;
    43→        media-management)  echo "402" ;;
    44→        monitoring)        echo "500" ;;
    45→        openwebui)         echo "501" ;;
    46→        n8n)               echo "502" ;;
    47→        *)                 echo "" ;;
    48→    esac
    49→}
    50→
    51→# Get app name by container ID
    52→# Usage: APP=$(get_app_name 501)
    53→get_app_name() {
    54→    local vmid="$1"
    55→    case "$vmid" in
    56→        101) echo "network-services" ;;
    57→        200) echo "traefik" ;;
    58→        201) echo "dashboards" ;;
    59→        202) echo "authelia" ;;
    60→        304) echo "immich" ;;
    61→        401) echo "jellyfin" ;;
    62→        402) echo "media-management" ;;
    63→        500) echo "monitoring" ;;
    64→        501) echo "openwebui" ;;
    65→        502) echo "n8n" ;;
    66→        *)   echo "" ;;
    67→    esac
    68→}
    69→
    70→# List all app names
    71→# Usage: list_apps
    72→list_apps() {
    73→    echo "network-services traefik dashboards authelia immich jellyfin media-management monitoring openwebui n8n" | tr ' ' '\n' | sort
    74→}
    75→
    76→# Check if app exists
    77→# Usage: if app_exists "openwebui"; then ...
    78→app_exists() {
    79→    local app="$1"
    80→    local vmid
    81→    vmid=$(get_container_id "$app")
    82→    [[ -n "$vmid" ]]
    83→}
    84→
    85→# Print formatted app list for help messages
    86→print_app_list() {
    87→    echo "Available apps:"
    88→    printf "  %-20s (ID: %s)\n" "authelia" "202"
    89→    printf "  %-20s (ID: %s)\n" "dashboards" "201"
    90→    printf "  %-20s (ID: %s)\n" "immich" "304"
    91→    printf "  %-20s (ID: %s)\n" "jellyfin" "401"
    92→    printf "  %-20s (ID: %s)\n" "media-management" "402"
    93→    printf "  %-20s (ID: %s)\n" "monitoring" "500"
    94→    printf "  %-20s (ID: %s)\n" "n8n" "502"
    95→    printf "  %-20s (ID: %s)\n" "network-services" "101"
    96→    printf "  %-20s (ID: %s)\n" "openwebui" "501"
    97→    printf "  %-20s (ID: %s)\n" "traefik" "200"
    98→}
