// =============================================================================
// Grafana Alloy Configuration - Monitoring LXC
// =============================================================================
// Replaces OTEL Collector. Handles:
// - OTLP receiver (backwards compat for Proxmox/Immich)
// - Docker log collection
// - Journal log collection
// - Host metrics
// =============================================================================

// -----------------------------------------------------------------------------
// OTLP Receiver (backwards compatibility with Proxmox/Immich)
// -----------------------------------------------------------------------------
otelcol.receiver.otlp "default" {
  grpc {
    endpoint = "0.0.0.0:4317"
  }
  http {
    endpoint = "0.0.0.0:4318"
  }

  output {
    metrics = [otelcol.exporter.prometheus.default.input]
    logs    = [otelcol.exporter.loki.default.input]
    traces  = [] // Not storing traces yet
  }
}

otelcol.exporter.prometheus "default" {
  forward_to = [prometheus.remote_write.default.receiver]
}

otelcol.exporter.loki "default" {
  forward_to = [loki.write.default.receiver]
}

// -----------------------------------------------------------------------------
// Docker Log Discovery
// -----------------------------------------------------------------------------
discovery.docker "containers" {
  host = "unix:///var/run/docker.sock"
}

discovery.relabel "docker_logs" {
  targets = discovery.docker.containers.targets

  // Keep container name as label
  rule {
    source_labels = ["__meta_docker_container_name"]
    regex         = "/(.*)"
    target_label  = "container"
  }

  // Add compose service name if available
  rule {
    source_labels = ["__meta_docker_container_label_com_docker_compose_service"]
    target_label  = "service"
  }

  // Add LXC identifier
  rule {
    target_label = "lxc"
    replacement  = "monitoring"
  }

  rule {
    target_label = "lxc_id"
    replacement  = "500"
  }
}

loki.source.docker "containers" {
  host       = "unix:///var/run/docker.sock"
  targets    = discovery.relabel.docker_logs.output
  forward_to = [loki.write.default.receiver]
}

// -----------------------------------------------------------------------------
// Journal Logs (systemd)
// -----------------------------------------------------------------------------
loki.source.journal "systemd" {
  forward_to = [loki.process.journal.receiver]
  labels = {
    job    = "journal",
    lxc    = "monitoring",
    lxc_id = "500",
  }
}

loki.process "journal" {
  forward_to = [loki.write.default.receiver]

  stage.static_labels {
    values = {
      source = "journal",
    }
  }
}

// -----------------------------------------------------------------------------
// Loki Write Endpoint
// -----------------------------------------------------------------------------
loki.write "default" {
  endpoint {
    url = "http://loki:3100/loki/api/v1/push"
  }
}

// -----------------------------------------------------------------------------
// Prometheus Remote Write
// -----------------------------------------------------------------------------
prometheus.remote_write "default" {
  endpoint {
    url = "http://prometheus:9090/api/v1/write"
  }
}

# Monitoring Stack Environment Variables
# Generated from OpenTofu - do not edit manually

# Grafana admin password
GRAFANA_ADMIN_PASSWORD=${grafana_admin_password}

# Uptime Kuma credentials (for AutoKuma management)
UPTIME_KUMA_USERNAME=${uptime_kuma_username}
UPTIME_KUMA_PASSWORD=${uptime_kuma_password}

# Discord webhook for notifications
DISCORD_WEBHOOK_URL=${discord_webhook_url}

# =============================================================================
# 1Password Provider Configuration
# =============================================================================
# This file provides direct 1Password integration for secret management.
# Secrets are fetched at plan/apply time using the 1Password CLI.
#
# Authentication: Uses 1Password CLI with biometric unlock
# Ensure `op` CLI v2.23.0+ is installed and signed in
#
# Usage: Symlink this file to any app that needs 1Password secrets
#   ln -s ../../../onepassword.tf tofu/apps/<app>/onepassword.tf
# =============================================================================

# -----------------------------------------------------------------------------
# 1Password Vault Reference
# -----------------------------------------------------------------------------

data "onepassword_vault" "homelab" {
  name = "homelab"
}

# -----------------------------------------------------------------------------
# Core Infrastructure Secrets
# -----------------------------------------------------------------------------

# OpenTofu state encryption and Proxmox credentials
data "onepassword_item" "opentofu" {
  vault = data.onepassword_vault.homelab.uuid
  title = "opentofu"
}

# -----------------------------------------------------------------------------
# Cloudflare Secrets
# -----------------------------------------------------------------------------

data "onepassword_item" "cloudflare" {
  vault = data.onepassword_vault.homelab.uuid
  title = "Cloudflare"
}

# -----------------------------------------------------------------------------
# Monitoring Secrets
# -----------------------------------------------------------------------------

data "onepassword_item" "grafana" {
  vault = data.onepassword_vault.homelab.uuid
  title = "grafana"
}

data "onepassword_item" "discord_webhook" {
  vault = data.onepassword_vault.homelab.uuid
  title = "discord-alertmanager-webhook"
}

data "onepassword_item" "uptime_kuma" {
  vault = data.onepassword_vault.homelab.uuid
  title = "uptime-kuma"
}

# -----------------------------------------------------------------------------
# Container Management Secrets (Pulse + Arcane)
# -----------------------------------------------------------------------------

data "onepassword_item" "pulse" {
  vault = data.onepassword_vault.homelab.uuid
  uuid  = "zi3pssvujqcc2zmshihgkmfkju" # "pulse" (lowercase LOGIN item)
}

data "onepassword_item" "arcane" {
  vault = data.onepassword_vault.homelab.uuid
  uuid  = "kqujk6bc3wloojsmulzbrdaaie" # "arcane" (lowercase LOGIN item)
}

# -----------------------------------------------------------------------------
# Agent Tokens (per-LXC tokens stored in centralized items)
# -----------------------------------------------------------------------------
# Structure: One item per agent type with sections for each LXC
#   pulse-agents:
#     n8n.token, immich.token, jellyfin.token, ...
#   arcane-agents:
#     n8n.bootstrap_token, immich.bootstrap_token, ...

data "onepassword_item" "pulse_agents" {
  vault = data.onepassword_vault.homelab.uuid
  title = "pulse-agents"
}

data "onepassword_item" "arcane_agents" {
  vault = data.onepassword_vault.homelab.uuid
  title = "arcane-agents"
}

# -----------------------------------------------------------------------------
# Helper Locals - Flatten 1Password fields for easy access
# -----------------------------------------------------------------------------
# The 1Password provider returns fields in a nested structure.
# Custom fields are inside section blocks.

locals {
  # Flatten all section fields from opentofu item into a map by label
  _opentofu_section_fields = merge([
    for s in data.onepassword_item.opentofu.section : {
      for f in s.field : f.label => f.value
    }
  ]...)

  # Flatten all section fields from cloudflare item into a map by label
  _cloudflare_section_fields = merge([
    for s in data.onepassword_item.cloudflare.section : {
      for f in s.field : f.label => f.value
    }
  ]...)

  # Flatten all section fields from arcane item into a map by label
  _arcane_section_fields = merge([
    for s in data.onepassword_item.arcane.section : {
      for f in s.field : f.label => f.value
    }
  ]...)

  # Flatten pulse-agents sections into map: { "n8n" = { "token" = "xxx" }, ... }
  _pulse_agents_by_lxc = {
    for s in try(data.onepassword_item.pulse_agents.section, []) : s.label => {
      for f in try(s.field, []) : f.label => f.value
    }
  }

  # Flatten arcane-agents sections into map: { "n8n" = { "bootstrap_token" = "xxx" }, ... }
  _arcane_agents_by_lxc = {
    for s in try(data.onepassword_item.arcane_agents.section, []) : s.label => {
      for f in try(s.field, []) : f.label => f.value
    }
  }

  # 1Password secrets - access via local.op.<secret_name>
  op = {
    # State encryption passphrase (main password field)
    state_encryption_passphrase = data.onepassword_item.opentofu.password

    # Proxmox API token (custom field in section)
    proxmox_api_token = lookup(local._opentofu_section_fields, "proxmox_api_token", "")

    # Cloudflare (custom fields in sections + standard fields)
    cloudflare_email        = data.onepassword_item.cloudflare.username
    cloudflare_tunnel_token = lookup(local._cloudflare_section_fields, "tunnel_token", "")
    cloudflare_api_token    = lookup(local._cloudflare_section_fields, "ddns_api_token", lookup(local._cloudflare_section_fields, "Api token - traefik", ""))
    cloudflare_dns_token    = lookup(local._cloudflare_section_fields, "Api token - traefik", "")

    # Monitoring
    grafana_admin_password  = data.onepassword_item.grafana.password
    discord_webhook_url     = data.onepassword_item.discord_webhook.credential
    uptime_kuma_username    = data.onepassword_item.uptime_kuma.username
    uptime_kuma_password    = data.onepassword_item.uptime_kuma.password

    # Container Management (Pulse + Arcane)
    pulse_admin_user     = data.onepassword_item.pulse.username
    pulse_admin_password = data.onepassword_item.pulse.password
    arcane_encryption_key = lookup(local._arcane_section_fields, "encryption_key", "")
    arcane_jwt_secret     = lookup(local._arcane_section_fields, "jwt_secret", "")
  }

  # Agent tokens by LXC name - access via local.agent_tokens["n8n"].pulse_token
  # Each entry has .pulse_token and .arcane_bootstrap_token
  agent_tokens = {
    for lxc_name in distinct(concat(
      keys(local._pulse_agents_by_lxc),
      keys(local._arcane_agents_by_lxc)
    )) : lxc_name => {
      pulse_token            = try(local._pulse_agents_by_lxc[lxc_name]["token"], "")
      arcane_bootstrap_token = try(local._arcane_agents_by_lxc[lxc_name]["bootstrap_token"], "")
    }
  }
}

# =============================================================================
# Traefik Route Module
# =============================================================================
# Generates and syncs Traefik dynamic configuration for an app.
# Each app can self-register its routes without modifying Traefik configs.
#
# Features:
# - Auto-generates YAML config from variables
# - Syncs to Traefik LXC via file-sync module
# - Supports internal (websecure) and public (web) routes
# - Health checks, middlewares, custom options
#
# Usage:
#   module "n8n_route" {
#     source = "../../modules/traefik-route"
#
#     app_name    = "n8n"
#     backend_url = "http://192.168.1.213:5678"
#
#     internal_domain = "n8n.homelab.rambtech.dev"
#     public_domain   = ""  # Optional
#
#     traefik_host         = "192.168.1.162"
#     ssh_private_key_path = var.ssh_private_key_path
#   }
# =============================================================================

terraform {
  required_providers {
    local = {
      source = "hashicorp/local"
    }
    filesync = {
      source = "darshan-rambhia/filesync"
    }
    ansible = {
      source  = "marshallford/ansible"
      version = "~> 0.9"
    }
  }
}

# -----------------------------------------------------------------------------
# Route Configuration Templates
# -----------------------------------------------------------------------------

locals {
  # Internal route (websecure with TLS)
  internal_route = var.internal_domain != "" ? {
    rule        = "Host(`${var.internal_domain}`)"
    entryPoints = var.internal_entrypoint
    service     = var.app_name
    tls = {
      certResolver = var.cert_resolver
    }
    middlewares = var.internal_middlewares
  } : null

  # Public route (web HTTP - Cloudflare Flexible SSL forwards HTTP to origin)
  public_route = var.public_domain != "" ? {
    rule        = "Host(`${var.public_domain}`)"
    entryPoints = var.public_entrypoint
    service     = var.app_name
    middlewares = var.public_middlewares
  } : null

  # Service configuration
  service_config = {
    loadBalancer = merge(
      {
        servers = [
          { url = var.backend_url }
        ]
      },
      var.health_check != null ? { healthCheck = var.health_check } : {}
    )
  }

  # Complete Traefik config
  traefik_config = {
    http = {
      routers = merge(
        local.internal_route != null ? { "${var.app_name}" = local.internal_route } : {},
        local.public_route != null ? { "${var.app_name}-public" = local.public_route } : {}
      )
      services = {
        "${var.app_name}" = local.service_config
      }
    }
  }

  # YAML output
  config_yaml = yamlencode(local.traefik_config)

  # Target path on Traefik LXC
  remote_config_path = "/config/dynamic/${var.app_name}.yml"
}

# -----------------------------------------------------------------------------
# Write Config to Temporary File
# -----------------------------------------------------------------------------

resource "local_file" "route_config" {
  content  = local.config_yaml
  filename = "${path.module}/.tmp/${var.app_name}.yml"

  # Create directory if needed
  provisioner "local-exec" {
    command = "mkdir -p ${path.module}/.tmp"
    when    = create
  }
}

# -----------------------------------------------------------------------------
# Sync to Traefik LXC using filesync provider
# -----------------------------------------------------------------------------

resource "filesync_file" "traefik_route" {
  source      = local_file.route_config.filename
  destination = local.remote_config_path
  host        = var.traefik_host

  # SSH configuration
  ssh_key_path = var.ssh_private_key_path

  # File permissions
  owner = "root"
  group = "root"
  mode  = "0644"

  depends_on = [local_file.route_config]
}

# -----------------------------------------------------------------------------
# Reload Traefik Configuration via Ansible
# -----------------------------------------------------------------------------
# Sends SIGUSR1 to Traefik process for graceful config reload (no restart)

resource "ansible_navigator_run" "reload_traefik" {
  count = var.reload_traefik ? 1 : 0

  depends_on = [filesync_file.traefik_route]

  triggers = {
    config_hash = local_file.route_config.content
  }

  execution_environment = {
    enabled = false  # Run ansible directly on host
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.ssh_private_key_path)
    }]
  }

  playbook = <<-EOT
    - name: Reload Traefik configuration
      hosts: traefik
      gather_facts: no
      vars:
        app_name: ${var.app_name}

      tasks:
        # =====================================================================
        # Graceful Reload - SIGUSR1 triggers config reload without restart
        # =====================================================================
        - name: Send SIGUSR1 to Traefik for config reload
          ansible.builtin.command:
            cmd: docker exec traefik kill -USR1 1
          register: reload_result
          failed_when: reload_result.rc != 0
          changed_when: true

        - name: Display reload status
          ansible.builtin.debug:
            msg: "Traefik configuration reloaded for {{ app_name }}"
  EOT

  inventory = yamlencode({
    traefik = {
      hosts = {
        traefik = {
          ansible_host = var.traefik_host
          ansible_user = "root"
        }
      }
    }
  })
}

# -----------------------------------------------------------------------------
# Cleanup Temp File
# -----------------------------------------------------------------------------
# Note: Temp files are left in .tmp/ directory for debugging
# They can be safely deleted manually or via .gitignore

# =============================================================================
# Traefik Route Module - Variables
# =============================================================================

# -----------------------------------------------------------------------------
# Required Variables
# -----------------------------------------------------------------------------

variable "app_name" {
  description = "Name of the app (used for router/service names and config filename)"
  type        = string
}

variable "backend_url" {
  description = "Backend URL (e.g., http://192.168.1.213:5678)"
  type        = string
}

variable "traefik_host" {
  description = "Traefik LXC IP address"
  type        = string
}

variable "ssh_private_key_path" {
  description = "Path to SSH private key for Traefik LXC access"
  type        = string
}

# -----------------------------------------------------------------------------
# Domain Configuration
# -----------------------------------------------------------------------------

variable "internal_domain" {
  description = "Internal domain (e.g., n8n.homelab.rambtech.dev) - Leave empty to disable"
  type        = string
  default     = ""
}

variable "public_domain" {
  description = "Public domain (e.g., n8n.rambtech.dev) - Leave empty to disable"
  type        = string
  default     = ""
}

# -----------------------------------------------------------------------------
# Route Options
# -----------------------------------------------------------------------------

variable "internal_entrypoint" {
  description = "Traefik entrypoint for internal route"
  type        = list(string)
  default     = ["websecure"]
}

variable "public_entrypoint" {
  description = "Traefik entrypoint for public route"
  type        = list(string)
  default     = ["web"]
}

variable "internal_middlewares" {
  description = "List of middlewares for internal route"
  type        = list(string)
  default     = [ "security-headers", "internal-only" ]
}

variable "public_middlewares" {
  description = "List of middlewares for public route"
  type        = list(string)
  default     = ["public-security"]
}

variable "cert_resolver" {
  description = "TLS certificate resolver name"
  type        = string
  default     = "letsencrypt"
}

variable "health_check" {
  description = "Health check configuration (null to disable)"
  type = object({
    path     = optional(string, "/")
    interval = optional(string, "10s")
    timeout  = optional(string, "3s")
  })
  default = null
}

# -----------------------------------------------------------------------------
# Deployment Options
# -----------------------------------------------------------------------------

variable "reload_traefik" {
  description = "Send reload signal to Traefik after config update"
  type        = bool
  default     = true
}

variable "cleanup_temp_files" {
  description = "Delete temporary config files on destroy"
  type        = bool
  default     = true
}

# =============================================================================
# LXC Sidecars Module Variables
# =============================================================================
# This module manages sidecar services for LXC containers:
#   - Backup (proxmox-backup-client with PBS)
#   - Alloy (Grafana Alloy for log/metric collection)
#   - DIUN (Docker image update notifications) - Future
# =============================================================================

# =============================================================================
# Container Information
# =============================================================================

variable "container_id" {
  description = "LXC container ID"
  type        = number
}

variable "container_ip" {
  description = "Container IP address (without CIDR)"
  type        = string
}

variable "container_name" {
  description = "Container hostname"
  type        = string
}

# =============================================================================
# Proxmox SSH Connection (for Ansible deployment)
# =============================================================================

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address"
  type        = string
}

variable "proxmox_ssh_private_key_path" {
  description = "Path to SSH private key for Proxmox host"
  type        = string
}

# =============================================================================
# Backup Configuration
# =============================================================================

variable "backup" {
  description = "Backup configuration for PBS client"
  type = object({
    enabled     = bool
    schedule    = string                    # "daily", "02:00", "Sun 03:00"
    retention   = optional(string, "7")     # Keep N backups
    namespace   = string                    # PBS namespace (usually container name)

    # Pre-backup commands (database dumps, etc.)
    pre_backup_commands = optional(list(object({
      name    = string
      command = string
      timeout = optional(number, 300)
    })), [])

    # Paths to backup/exclude
    include_paths = optional(list(string), ["/config"])
    exclude_paths = optional(list(string), ["/var/lib/docker/overlay2"])

    # PBS server settings
    pbs_server     = optional(string, "10.100.1.102")
    pbs_datastore  = optional(string, "homelab")
    pbs_user       = optional(string, "backup@pbs")
    pbs_password_cmd = optional(string, "op read 'op://homelab/PBS - Proxmox Backup Server/password'")

    # Alert settings
    ntfy_url      = optional(string, "http://10.100.5.100:8080/homelab-alerts")
    ntfy_priority = optional(string, "default")
    ntfy_tags     = optional(string, "backup")
  })
  default = null

  validation {
    condition = var.backup == null || (
      var.backup.enabled == true && var.backup.namespace != ""
    )
    error_message = "If backup is enabled, namespace must be provided."
  }

  validation {
    condition = var.backup == null || (
      var.backup.schedule == "daily" ||
      can(regex("^[0-9]{2}:[0-9]{2}$", var.backup.schedule)) ||
      can(regex("^(mon|tue|wed|thu|fri|sat|sun) [0-9]{2}:[0-9]{2}$", lower(var.backup.schedule)))
    )
    error_message = "Schedule must be 'daily', 'HH:MM', or 'day HH:MM' (e.g., 'Sun 03:00')."
  }
}

# =============================================================================
# Container Management Agents
# =============================================================================

variable "pulse_agent" {
  description = "Pulse Docker agent configuration for container monitoring"
  type = object({
    enabled     = optional(bool, false)
    pulse_url   = optional(string, "http://10.100.1.104:7655")
    pulse_token = optional(string, "")
  })
  default = {}

  validation {
