input.command:
ssh root@10.100.5.100 "mkdir -p /config/monitoring/ntfy/templates && cat > /config/monitoring/ntfy/templates/alertmanager.yml" << 'EOF'
title: |
  {{- if eq .status "firing" }}
  🚨 Alert: {{ (first .alerts).labels.alertname }}
  {{- else if eq .status "resolved" }}
  ✅ Resolved: {{ (first .alerts).labels.alertname }}
  {{- else }}
  {{ fail "Unsupported Alertmanager status." }}
  {{- end }}
message: |
  Status: {{ .status | title }}
  Receiver: {{ .receiver }}

  {{- range .alerts }}
  Alert: {{ .labels.alertname }}
  Instance: {{ .labels.instance }}
  Severity: {{ .labels.severity }}
  Starts at: {{ .startsAt }}
  {{- if .endsAt }}
  Ends at: {{ .endsAt }}{{ end }}
  {{- if .annotations.summary }}
  Summary: {{ .annotations.summary }}
  {{- end }}
  {{- if .annotations.description }}
  Description: {{ .annotations.description }}
  {{- end }}
  Source: {{ .generatorURL }}

  {{ end }}
EOF

ssh root@10.100.5.100 'curl -XPOST http://localhost:9093/api/v2/alerts -H "Content-Type: application/json" -d "[{
  \"labels\": {
    \"alertname\": \"TemplateTest\",
    \"severity\": \"warning\",
    \"instance\": \"test-instance-v2\",
    \"job\": \"template-verification\"
  },
  \"annotations\": {
    \"summary\": \"Testing ntfy template after deployment\",
    \"description\": \"This alert should now be formatted with the alertmanager template - showing structured layout instead of raw JSON\"
  },
  \"generatorURL\": \"http://prometheus.homelab.rambtech.dev/template-test\"
}]" && echo ""'

