input.content:
# =============================================================================
# ntfy Template: Uptime Kuma
# =============================================================================
# Formats Uptime Kuma webhook notifications
# Usage: POST to ntfy with ?template=uptime-kuma
#
# Webhook payload structure:
# {
#   "heartbeat": { "status": 0|1, "msg": "...", "time": "...", "duration": 30 },
#   "monitor": { "name": "...", "url": "...", "type": "http", ... }
# }
# =============================================================================

# Title template
title: |
  {{- $status := .heartbeat.status -}}
  {{- $name := .monitor.name -}}
  {{- if eq $status 1.0 -}}
    ✅ UP: {{ $name }}
  {{- else if eq $status 0.0 -}}
    🚨 DOWN: {{ $name }}
  {{- else -}}
    ⚠️ {{ $name }}
  {{- end -}}

# Message template
message: |
  {{- $monitor := .monitor -}}
  {{- $heartbeat := .heartbeat -}}
  {{- $status := .heartbeat.status -}}

  Monitor: {{ $monitor.name }}
  Status: {{- if eq $status 1.0 }} UP ✓{{- else if eq $status 0.0 }} DOWN ✗{{- else }} UNKNOWN{{- end }}
  Type: {{ $monitor.type | upper }}
  {{- if $monitor.url }}
  URL: {{ $monitor.url }}
  {{- end }}

  {{- if $heartbeat.msg }}
  Message: {{ $heartbeat.msg }}
  {{- end }}

  {{- if $heartbeat.duration }}
  Response Time: {{ $heartbeat.duration }}ms
  {{- end }}

  {{- if $heartbeat.time }}
  Timestamp: {{ $heartbeat.time }}
  {{- end }}

